import{z as n,x as A,o,c as p,q as s,j as l,D as E,d as r,s as B,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"网络策略","description":"","frontmatter":{"title":"网络策略","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-network-policy.md","filePath":"cs/orch-network-policy.md","lastUpdated":1791063341000}'),d={name:"cs/orch-network-policy.md"};function c(C,e,D,m,F,P){const t=A("Mermaid");return o(),p("div",null,[e[2]||(e[2]=s('<h1 id="网络策略" tabindex="-1">网络策略 <a class="header-anchor" href="#网络策略" aria-label="Permalink to &quot;网络策略&quot;">​</a></h1><div class="epigraph"><p>容器网络的默认语义是一张无差别的全通网；写策略不是加规则，是从全通里往外抠。</p><footer>—— 据 Kubernetes 官方文档（Network Policies）与数据中心 CNI 实践整理</footer></div><p><a href="/cs/orch-multitenant-policy">上一课</a>把 namespace 钉成行政边界，并明说它不隔离网络；本课补上网络这一维。数据面的每包路径——进出命名空间、过滤链、封装——<a href="/cs/virt-network-virtualization">网络虚拟化</a> 已算过每包的账；本课管语义层：一条 NetworkPolicy 声明了什么，它被谁编译到那条每包路径上，以及「选中即收紧」这套语法为什么长这样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平网的代价在多租户时结算：任何一个被攻破的 pod 可以横向连通段内一切服务——数据库、缓存、元数据接口全部在同一张全通网里。缺口是三层与四层的「谁可以连谁」要能声明、能编译、能审计：声明写成人能读的对象，编译成每包过滤，审计时能回答「这条流为什么被放行」。缺了中间的编译环节，策略就只是写给审计看的装饰。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象三件套：podSelector 决定<strong>管谁</strong>；ingress 与 egress 规则决定<strong>放行什么</strong>；对端（peer）用同段的 podSelector、跨段的 namespaceSelector 或网段（ipBlock）表达。语义一句话：<strong>被任何策略选中的 pod 立即进入白名单模式——未被允许的一律拒绝；未被任何策略选中的 pod 保持全通</strong>。所以「默认拒绝」要显式写：空规则的策略选中全段 pod，就把整段抠成白名单。规则之间是加法并集——两条策略各自允许的流加在一起，语言里不存在 deny 条目。编译由 CNI 承担：iptables 链或 eBPF 程序挂在每包路径上，按连接跟踪放行已建立连接的回包——策略是状态化的，不是逐包独立判。</p><p><span class="marginnote">术语翻译：NetworkPolicy 就是「从全通网里往外抠」的 ACL 清单——podSelector 圈出管谁，ingress/egress 列出放行谁的哪些端口。像小区装门禁：被选中的楼（pod）刷卡才能进，没被选中的楼维持谁都能进；装了门禁不代表欢迎访客，只代表「不刷卡一律拦」。</span></p>',8)),(o(),l(i,null,{default:E(()=>[B(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22NetworkPolicy%20%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20SEL%5B%22podSelector%20%E9%80%89%E4%B8%AD%E7%9B%AE%E6%A0%87%20pod%22%5D%0A%20%20SEL%20--%3E%20MODE%5B%22%E7%99%BD%E5%90%8D%E5%8D%95%E6%A8%A1%E5%BC%8F%E5%BC%80%E5%90%AF%22%5D%0A%20%20MODE%20--%3E%20COMPILE%5B%22CNI%20%E7%BC%96%E8%AF%91%E5%88%B0%E6%AF%8F%E5%8C%85%E8%BF%87%E6%BB%A4%22%5D%0A%20%20COMPILE%20--%3E%20PKT%5B%22%E6%AF%8F%E5%8C%85%3A%20%E6%9F%A5%E5%85%81%E8%AE%B8%E9%9B%86%E4%B8%8E%E8%BF%9E%E6%8E%A5%E8%B7%9F%E8%B8%AA%22%5D%0A%20%20PKT%20--%3E%20HIT%7B%22%E5%91%BD%E4%B8%AD%E5%85%81%E8%AE%B8%E6%88%96%E5%B7%B2%E5%BB%BA%E7%AB%8B%3F%22%7D%0A%20%20HIT%20--%3E%7C%22%E6%98%AF%22%7C%20FWD%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"「选中即收紧」与「无 deny 条目」是同一个设计的两面：允许集只会单调扩张，审计因此变成可枚举的事——把所有策略按「选中集合」分组，每组的并集就是该组 pod 的全部入口。想拒绝某条流，唯一的办法是调整选择器，让这条流落出允许集；把这层语义当传统防火墙的规则序列用（指望后写的覆盖先写的），会得到与直觉相反的结果。跨段引用让上一课的行政边界获得网络含义：namespaceSelector 指向段，段内 pod 集合变了，策略跟着调和——策略与配额一样挂在 namespace 坐标上。",-1)),e[5]||(e[5]=a("p",null,"能力的边界钉在四层：域名（FQDN）与七层协议字段不在原生语义里，要换 CNI 的扩展对象——表达力与可移植性的交换：用了扩展，策略就绑定了那家实现。收紧 egress 的第一步几乎总是放行 DNS：命名解析是第一依赖，掐死它，所有连接超时都以「网络策略误伤」的面目出现。",-1)),(o(),l(i,null,{default:E(()=>[B(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22Pod%20%E6%83%B3%E8%BF%9E%20api.example.com%22%5D%20--%3E%20DNSQ%5B%22%E5%85%88%E5%8F%91%20DNS%20%E6%9F%A5%E8%AF%A2%E6%8B%BF%20IP%22%5D%0A%20%20DNSQ%20--%3E%7C%22egress%20%E5%85%81%E8%AE%B8%E9%9B%86%E6%B2%A1%E6%94%BE%E8%A1%8C%2053%20%E7%AB%AF%E5%8F%A3%22%7C%20LOST%5B%22%E6%9F%A5%E8%AF%A2%E5%8C%85%E8%A2%AB%E4%B8%A2%22%5D%0A%20%20LOST%20--%3E%20TMO%5B%22%E5%BA%94%E7%94%A8%E5%B1%82%E7%AD%89%E4%B8%8D%E5%88%B0%E8%A7%A3%E6%9E%90%2C%20%E8%BF%9E%E6%8E%A5%E8%B6%85%E6%97%B6%22%5D%0A%20%20DNSQ%20--%3E%7C%22%E6%94%BE%E8%A1%8C%E4%BA%86%20kube-dns%22%7C%20RES%5B%22%E6%8B%BF%E5%88%B0%20IP%20%E4%B8%8E%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20RES%20--%3E%20CHK%7B%22%E7%9B%AE%E7%9A%84%E5%9C%B0%E5%9C%A8%E5%85%81%E8%AE%B8%E9%9B%86%E5%86%85%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20CONN%5B%22%E6%94%BE%E8%A1%8C%E5%B9%B6%E5%BB%BA%E7%AB%8B%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20DRP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<p><span class="marginnote">直觉类比：允许集像一块只加不擦的白名单白板——每条新策略只会往里添名字，语言里没有「擦掉」（deny）这个动作。想让某人进不来，只能改选择器、让规则不再覆盖到他，而不是在板上写「禁止他」；指望后写的策略覆盖先写的，会得到与防火墙经验相反的结果。</span></p><p><span class="marginnote">易错点：空 podSelector 选中段内全部 pod——写「对某类 pod 收紧」时漏了它自己也会被别的策略选中收紧，排查时要把「谁选中了谁」逐条列出，而不是看单条规则。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>策略是意图，不是证据：真正生效的是 CNI 编译出的过滤程序，实现缺陷或 CNI 不支持时策略会被静默忽略——审计必须落到数据面验证，不能停在对象存在。ipBlock 直接放行网段会绕过段与标签的语义，混用时要单列。加密与身份（mTLS）是网格的题；本课的「允许」是地址与端口的允许，不是身份的认证。</p><p><span class="marginnote">常见误区：初学者容易把「kubectl 里能看到 NetworkPolicy 对象」当成「策略在生效」。CNI 不支持时会静默忽略策略，对象照常创建、实际全网仍互通；验证要真打一条流——从另一个 pod 连一下被保护的端口，看到拒绝才算数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语义核心是「选中即白名单」：未被策略选中的 pod 保持全通，默认拒绝要显式写。</li><li>规则是加法并集，没有 deny；拒绝只能靠调整选择器让流落出允许集。</li><li>编译在 CNI：iptables 链或 eBPF 程序，配合连接跟踪状态化放行。</li><li>原生能力钉在四层；FQDN 与七层要换扩展，代价是绑定实现。</li><li>出处：Kubernetes 官方文档（Network Policies）；每包路径的账见网络虚拟化课。</li></ul>',7))])}const u=n(d,[["render",c]]);export{N as __pageData,u as default};
